import React, { useEffect, useState } from 'react';
import {
  View,
  ScrollView,
  StyleSheet,
  RefreshControl,
  TouchableOpacity,
} from 'react-native';
import {
  Card,
  Title,
  Paragraph,
  Button,
  Text,
  Surface,
  IconButton,
  ProgressBar,
  Chip,
  FAB,
} from 'react-native-paper';
import { LineChart } from 'react-native-chart-kit';
import { Dimensions } from 'react-native';
import { useQuery } from 'react-query';
import { analyticsApi } from '../services/analytics.api';
import { referralApi } from '../services/referral.api';
import { useAuthStore } from '../stores/authStore';

const screenWidth = Dimensions.get('window').width;

export const DashboardScreen = ({ navigation }: any) => {
  const { user } = useAuthStore();
  const [refreshing, setRefreshing] = useState(false);

  const { data: stats, refetch: refetchStats } = useQuery(
    'userStats',
    analyticsApi.getUserStats,
    {
      refetchInterval: 30000, // Refresh every 30 seconds
    }
  );

  const { data: recentLinks } = useQuery(
    'recentLinks',
    () => referralApi.getUserLinks({ limit: 5 }),
  );

  const onRefresh = async () => {
    setRefreshing(true);
    await refetchStats();
    setRefreshing(false);
  };

  const chartData = {
    labels: stats?.chartData?.labels || ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
    datasets: [
      {
        data: stats?.chartData?.clicks || [0, 0, 0, 0, 0, 0, 0],
        color: (opacity = 1) => `rgba(134, 65, 244, ${opacity})`,
        strokeWidth: 2,
      },
      {
        data: stats?.chartData?.conversions || [0, 0, 0, 0, 0, 0, 0],
        color: (opacity = 1) => `rgba(34, 197, 94, ${opacity})`,
        strokeWidth: 2,
      },
    ],
  };

  return (
    <View style={styles.container}>
      <ScrollView
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
        }
      >
        {/* Welcome Section */}
        <Card style={styles.welcomeCard}>
          <Card.Content>
            <Title>Welcome back, {user?.firstName}!</Title>
            <Paragraph>Your referral campaign is performing well</Paragraph>
          </Card.Content>
        </Card>

        {/* Stats Overview */}
        <View style={styles.statsContainer}>
          <Surface style={styles.statCard}>
            <Text style={styles.statValue}>{stats?.totalSent || 0}</Text>
            <Text style={styles.statLabel}>Links Sent</Text>
          </Surface>
          <Surface style={styles.statCard}>
            <Text style={styles.statValue}>{stats?.totalClicks || 0}</Text>
            <Text style={styles.statLabel}>Total Clicks</Text>
          </Surface>
          <Surface style={styles.statCard}>
            <Text style={styles.statValue}>{stats?.conversions || 0}</Text>
            <Text style={styles.statLabel}>Conversions</Text>
          </Surface>
          <Surface style={styles.statCard}>
            <Text style={styles.statValue}>
              {stats?.conversionRate || 0}%
            </Text>
            <Text style={styles.statLabel}>Conv. Rate</Text>
          </Surface>
        </View>

        {/* Performance Chart */}
        <Card style={styles.chartCard}>
          <Card.Content>
            <Title>Weekly Performance</Title>
            <LineChart
              data={chartData}
              width={screenWidth - 40}
              height={220}
              chartConfig={{
                backgroundColor: '#ffffff',
                backgroundGradientFrom: '#ffffff',
                backgroundGradientTo: '#ffffff',
                decimalPlaces: 0,
                color: (opacity = 1) => `rgba(0, 0, 0, ${opacity})`,
                labelColor: (opacity = 1) => `rgba(0, 0, 0, ${opacity})`,
                style: {
                  borderRadius: 16,
                },
                propsForDots: {
                  r: '6',
                  strokeWidth: '2',
                  stroke: '#ffa726',
                },
              }}
              bezier
              style={{
                marginVertical: 8,
                borderRadius: 16,
              }}
            />
            <View style={styles.legendContainer}>
              <Chip icon="circle" textStyle={{ color: '#8641f4' }}>
                Clicks
              </Chip>
              <Chip icon="circle" textStyle={{ color: '#22c55e' }}>
                Conversions
              </Chip>
            </View>
          </Card.Content>
        </Card>

        {/* Recent Links */}
        <Card style={styles.recentLinksCard}>
          <Card.Content>
            <View style={styles.sectionHeader}>
              <Title>Recent Links</Title>
              <Button
                mode="text"
                onPress={() => navigation.navigate('MyLinks')}
              >
                View All
              </Button>
            </View>
            {recentLinks?.map((link: any) => (
              <TouchableOpacity
                key={link.id}
                onPress={() =>
                  navigation.navigate('LinkDetails', { linkId: link.id })
                }
              >
                <Surface style={styles.linkItem}>
                  <View style={styles.linkInfo}>
                    <Text style={styles.linkCode}>/{link.shortCode}</Text>
                    <Text style={styles.linkStats}>
                      {link.clicks} clicks • {link.conversions} conversions
                    </Text>
                  </View>
                  <IconButton icon="chevron-right" size={20} />
                </Surface>
              </TouchableOpacity>
            ))}
          </Card.Content>
        </Card>

        {/* Quick Actions */}
        <Card style={styles.actionsCard}>
          <Card.Content>
            <Title>Quick Actions</Title>
            <View style={styles.actionsGrid}>
              <Button
                mode="contained"
                icon="link-plus"
                onPress={() => navigation.navigate('CreateLink')}
                style={styles.actionButton}
              >
                New Link
              </Button>
              <Button
                mode="contained"
                icon="send"
                onPress={() => navigation.navigate('SendReferral')}
                style={styles.actionButton}
              >
                Send Referral
              </Button>
              <Button
                mode="contained"
                icon="contacts"
                onPress={() => navigation.navigate('Contacts')}
                style={styles.actionButton}
              >
                Import Contacts
              </Button>
              <Button
                mode="contained"
                icon="chart-line"
                onPress={() => navigation.navigate('Analytics')}
                style={styles.actionButton}
              >
                View Analytics
              </Button>
            </View>
          </Card.Content>
        </Card>
      </ScrollView>

      {/* Floating Action Button */}
      <FAB
        style={styles.fab}
        icon="plus"
        onPress={() => navigation.navigate('CreateLink')}
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
  },
  welcomeCard: {
    margin: 16,
    elevation: 2,
  },
  statsContainer: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    marginBottom: 16,
  },
  statCard: {
    width: '48%',
    padding: 16,
    marginBottom: 12,
    borderRadius: 8,
    elevation: 2,
    alignItems: 'center',
  },
  statValue: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#333',
  },
  statLabel: {
    fontSize: 12,
    color: '#666',
    marginTop: 4,
  },
  chartCard: {
    margin: 16,
    elevation: 2,
  },
  legendContainer: {
    flexDirection: 'row',
    justifyContent: 'center',
    gap: 16,
    marginTop: 12,
  },
  recentLinksCard: {
    margin: 16,
    elevation: 2,
  },
  sectionHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 12,
  },
  linkItem: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 12,
    marginVertical: 4,
    borderRadius: 8,
    elevation: 1,
  },
  linkInfo: {
    flex: 1,
  },
  linkCode: {
    fontSize: 16,
    fontWeight: '600',
    color: '#333',
  },
  linkStats: {
    fontSize: 12,
    color: '#666',
    marginTop: 4,
  },
  actionsCard: {
    margin: 16,
    marginBottom: 80,
    elevation: 2,
  },
  actionsGrid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 12,
    marginTop: 12,
  },
  actionButton: {
    flex: 1,
    minWidth: '45%',
  },
  fab: {
    position: 'absolute',
    margin: 16,
    right: 0,
    bottom: 0,
    backgroundColor: '#6200ee',
  },
});
